function defineTranslations(translations: TranslationTable): TranslationTable {
  return translations;
}

function toTraditionalChinese(table: TranslationTable): TranslationTable {
  const replacements: Array<[string, string]> = [
    ['简体中文', '簡體中文'], ['书库', '書庫'], ['文档', '文件'], ['设置', '設定'],
    ['默认', '預設'], ['编码', '編碼'], ['搜索', '搜尋'], ['页面', '頁面'],
    ['显示', '顯示'], ['当前', '目前'], ['打开', '開啟'], ['添加', '加入'],
    ['创建', '建立'], ['删除', '刪除'], ['重命名', '重新命名'], ['选择', '選擇'],
    ['颜色', '顏色'], ['配色', '配色'], ['浅白色', '淺白色'], ['暖色', '暖色'],
    ['冷色', '冷色'], ['护眼', '護眼'], ['点击', '點按'], ['文件夹', '資料夾'],
    ['路径', '路徑'], ['源文件', '來源檔案'], ['重新定位', '重新連結'], ['加载', '載入'],
    ['导入', '匯入'], ['返回', '返回'], ['保存', '儲存'], ['取消', '取消'],
    ['切换', '切換'], ['平铺', '格狀'], ['列表', '列表'], ['松手', '放開'],
    ['仅支持', '僅支援'], ['本地', '本機'], ['随时', '隨時'], ['阅读', '閱讀'],
    ['说明', '說明'], ['安装', '安裝'], ['故障', '疑難'], ['排查', '排解'],
    ['快速', '快速'], ['拖入', '拖入'], ['没有', '沒有'], ['换个', '換個'],
    ['关键词', '關鍵字'], ['清空', '清除'], ['重新', '重新'], ['上次', '上次'],
    ['继续', '繼續'], ['缺失', '遺失'], ['移除', '移除'], ['不会', '不會'],
    ['其中', '其中'], ['移动', '移至'], ['名称', '名稱'], ['无法', '無法'],
    ['正文', '內文'], ['目录', '目錄'], ['上一页', '上一頁'], ['下一页', '下一頁'],
    ['后退', '返回'], ['前进', '前進'], ['缩小', '縮小'], ['放大', '放大'],
    ['重置', '重設'], ['内容', '內容'], ['展开', '展開'], ['收起', '收合'],
    ['刷新', '重新整理'], ['范围', '範圍'], ['章节', '章節'], ['调整', '調整'],
    ['解析', '解析'], ['折叠', '收合'], ['涉及', '涵蓋'], ['切换', '切換'],
    ['外部链接', '外部連結'], ['界面', '介面'], ['应用', '應用程式'], ['柔和', '柔和'],
    ['亮度', '亮度'], ['错误', '錯誤'], ['窗口', '視窗'], ['查找', '尋找'],
    ['项目', '專案'], ['其它', '其他'], ['韩文', '韓文'], ['日文', '日文'],
    ['本文档', '份文件'], ['个文档', '份文件'], ['本文档', '份文件'], ['本书', '本書'],
  ];
  return Object.fromEntries(Object.entries(table).map(([key, value]) => [
    key,
    replacements.reduce((text, [from, to]) => text.replaceAll(from, to), value),
  ])) as TranslationTable;
}

