export function normalizeLocale(value: string | null | undefined): AppLocale {
  return supportedLocales.includes(value as AppLocale) ? value as AppLocale : 'zh-CN';
}

export function getLocaleDirection(locale: AppLocale): 'ltr' | 'rtl' {
  return locale === 'ar' ? 'rtl' : 'ltr';
}

export function normalizeTheme(value: string | null | undefined): AppTheme {
  return supportedThemes.includes(value as AppTheme) ? value as AppTheme : 'light';
}

export function translate(locale: AppLocale, key: TranslationKey, variables: Record<string, string | number> = {}): string {
  return translations[locale][key].replace(/\{([a-zA-Z]+)\}/g, (match, name: string) => (
    Object.hasOwn(variables, name) ? String(variables[name]) : match
  ));
}

export function getTranslationKeys(): TranslationKey[] {
  return Object.keys(zhCN) as TranslationKey[];
}
